-- Name: race_schedule_publications a_account_write_barrier; Type: TRIGGER; Schema: public; Owner: -
CREATE TRIGGER a_account_write_barrier BEFORE INSERT OR DELETE OR UPDATE ON public.race_schedule_publications FOR EACH ROW EXECUTE FUNCTION private.guard_account_write('select array_agg(distinct account order by account) filter(where account is not null) from (select a.account from public.profiles p1 cross join lateral (select (to_jsonb(p1)->>''id'')::uuid as account) a(account) where p1.id=($1->>''created_by'')::uuid union select a.account from public.profiles p1 cross join lateral (select (to_jsonb(p1)->>''id'')::uuid as account) a(account) where p1.id=($1->>''published_by'')::uuid) owners(account)', 'select ($1->>''created_by'' is not null and not exists(select 1 from public.profiles p where p.id=($1->>''created_by'')::uuid)) or ($1->>''published_by'' is not null and not exists(select 1 from public.profiles p where p.id=($1->>''published_by'')::uuid))');

-- Name: testing_contribution_reviews a_account_write_barrier; Type: TRIGGER; Schema: public; Owner: -
CREATE TRIGGER a_account_write_barrier BEFORE INSERT OR DELETE OR UPDATE ON public.testing_contribution_reviews FOR EACH ROW EXECUTE FUNCTION private.guard_account_write('select array_agg(distinct account order by account) filter(where account is not null) from (select a.account from public.testing_contributions p2 cross join lateral (select a.account from public.profiles p1 cross join lateral (select (to_jsonb(p1)->>''id'')::uuid as account) a(account) where p1.id=(to_jsonb(p2)->>''account_id'')::uuid) a(account) where p2.id=($1->>''contribution_id'')::uuid union select a.account from public.profiles p1 cross join lateral (select (to_jsonb(p1)->>''id'')::uuid as account) a(account) where p1.id=($1->>''reviewer'')::uuid) owners(account)', 'select ($1->>''contribution_id'' is not null and not exists(select 1 from public.testing_contributions p where p.id=($1->>''contribution_id'')::uuid)) or ($1->>''reviewer'' is not null and not exists(select 1 from public.profiles p where p.id=($1->>''reviewer'')::uuid))');
